// Single-palace observations and explicit, post-selection scenario calculations.
// No imports from chart presentation: shared by both tool transports and export.
import {computeStrength,STRENGTH_PROFILE} from './liuren-strength-engine.mjs';
import {fiveRelation,relations,hash} from './liuren-deterministic.mjs';
import {directedEffect,clip} from './liuren-strength-rules.mjs';

export const PALACE_MODEL='liuren-palace-strength-v1';
export const SELECTED_POLICY=Object.freeze({id:'liuren-selected-relations-v1',route_gate:.75,local_balance:'frozen',
 source_loss:'baseline-direct-greedy-and-binding',groups:false});
export const BANDS=[
 {range:'0',label:'本计算无有效力量'},
 {range:'0<E<1',label:'极弱，通常难以独立显著作用'},
 {range:'1≤E<2.5',label:'弱，仍有作用'},
 {range:'2.5≤E<5',label:'偏弱至中等，可发挥作用'},
 {range:'5≤E<7.5',label:'较强'},
 {range:'7.5≤E≤10',label:'强'}
];
export function strengthBand(e){
 if(e===null||e===undefined)return null;
 if(!Number.isFinite(e)||e<0||e>10)throw Error('旺衰分数须为0至10有限数；缺失不等于0');
 return BANDS[e===0?0:e<1?1:e<2.5?2:e<5?3:e<7.5?4:5].label;
}
const fail=m=>{throw Error('LIUREN_STRENGTH_ARGUMENTS: '+m);};
const text=(v)=>typeof v==='string'&&v.trim().length>0&&v.length<=1500;
export function palaceStrength(c,seasonProfile,{shensha}={}){
 return computeStrength(c,{seasonProfile,seasonBasis:'同盘固定月令条件表；不依预测结果选表',phase:'outcome'},{shensha});
}
export function palaceProfiles(c,{shensha}={}){
 const a=palaceStrength(c,'four-seasons',{shensha});
 return {'four-seasons':a,'quarter-earth':'辰未戌丑'.includes(c.month_branch)?palaceStrength(c,'quarter-earth',{shensha}):a};
}
// Strict even when the Codex adapter calls JS directly without the host's Zod.
export function calculateSelectedStrength(c,request,{evaluation,voidMode='included',quantityView=true}={}){
 const q=request??{},keys=['mode','season_profile','season_basis','actors','links','review'];
 if(Object.keys(q).some(k=>!keys.includes(k)))fail('未支持字段；不接受自定分数或系数');
 if(q.review!==undefined&&typeof q.review!=='boolean')fail('review须为布尔值');
 if(!['single_palace','selected_relations'].includes(q.mode))fail('mode须为single_palace/selected_relations');
 if(!['four-seasons','quarter-earth'].includes(q.season_profile)||!text(q.season_basis))fail('须明确season_profile及season_basis');
 if(!Array.isArray(q.actors)||!q.actors.length||q.actors.length>25)fail('须明确1至25个实际取用对象');
 const baseline=computeStrength(c,{seasonProfile:q.season_profile,seasonBasis:q.season_basis,phase:'outcome',voidMode,...(evaluation?{evaluation}:{})}),by=new Map(baseline.rows.filter(r=>r.kind!=='ground').map(r=>[r.id,r]));
 const actors=new Map();
 for(const a of q.actors){
  if(!a||Object.keys(a).some(k=>!['id','role','basis'].includes(k))||!by.has(a.id)||!text(a.role)||!text(a.basis))fail('actors须给本盘T:支/J:将/S:本日日干、role及取用basis');
  if(actors.has(a.id))fail('重复actor '+a.id);actors.set(a.id,a);
 }
 const links=q.links??[];
 if(!Array.isArray(links)||links.length>30)fail('links须为至多30项');
 if(q.mode==='single_palace'&&links.length)fail('single_palace不接收跨宫作用');
 if(q.mode==='selected_relations'&&!links.length)fail('selected_relations须提供已确认作用关系');
 const seen=new Set(),edges=[],skipped=[];
 for(const l of links){
  if(!l||Object.keys(l).some(k=>!['source','target','basis'].includes(k))||!text(l.basis)||!actors.has(l.source)||!actors.has(l.target)||l.source===l.target)fail('links双方须先取用并明确作用依据；不能自指');
  const key=[l.source,l.target].sort().join('|');
  if(seen.has(key))fail('同一对关系不得重复或反向重复计分');seen.add(key);
  const a=by.get(l.source),b=by.get(l.target),type=fiveRelation(a.symbol,b.symbol);
  if(!['生','克','比和'].includes(type))fail('source必须是施生/施克/比和方；实际关系为'+type);
  // A direct placement was already booked in at least one local view. Never
  // turn the same placement into a second reward/penalty after role selection.
  const existing=[...baseline.audit.ledger,...baseline.audit.blocked_edges].find(e=>e.source===l.source&&e.target===l.target&&e.type===type);
  if(existing){skipped.push({...l,type,reason:'直接位置关系已计入单宫或受原时序限制，不再叠加'});continue;}
  let blocked=null;
  if(type==='克'&&a.transmissions.includes(1)&&b.transmissions.includes(3)&&fiveRelation(b.symbol,c.day_stem)==='克')blocked='初不能制末鬼';
  if(blocked){skipped.push({...l,type,reason:blocked});continue;}
  edges.push({...l,type});
 }
 const p=STRENGTH_PROFILE,gates=new Map();
 // One fixed scenario gate; an actor cannot multiply its total source budget
 // by submitting numerous selected targets. Coefficients are not AI inputs.
 for(const e of edges)gates.set(e.source,(gates.get(e.source)??0)+SELECTED_POLICY.route_gate);
 for(const e of edges)e.gate=SELECTED_POLICY.route_gate/Math.max(1,gates.get(e.source)/p.inherited.relations.source_gate_budget);
 const ids=[...actors.keys()];
 function evaluate(values){
  const delta=Object.fromEntries(ids.map(id=>[id,0])),ledger=[];
  for(const e of edges){
   const a=by.get(e.source),tau=['生','克'].includes(e.type)?1-(a.goal_loss??0):1;
   const f=directedEffect(e.type,values[e.source],values[e.target],e.gate,a.seed,p,tau);
   delta[e.target]+=f.received;delta[e.source]-=f.cost;
   ledger.push({...e,tau,received:f.received,source_cost:f.cost});
  }
  const mapped=Object.fromEntries(ids.map(id=>{
   const b=by.get(id);
   // Re-use the baseline's raw local balance, not its already-attenuated E.
   // This applies void/access once and freezes unselected palaces.
   return [id,b.retention*clip(b.access*(b.base+b.delta+delta[id]))];
  }));
  return {mapped,delta,ledger};
 }
 const solutions=p.iteration.initial_values.map(start=>{
  let values=Object.fromEntries(ids.map(id=>[id,start])),residual,k=0;
  for(;k<p.iteration.max_iterations;k++){
   const v=evaluate(values);residual=Math.max(...ids.map(id=>Math.abs(v.mapped[id]-values[id])));
   if(residual<p.iteration.tolerance)break;
   values=Object.fromEntries(ids.map(id=>[id,values[id]+p.iteration.damping*(v.mapped[id]-values[id])]));
  }
  if(k===p.iteration.max_iterations)fail('补算未收敛');
  return {values,residual,iterations:k};
 });
 const spread=Math.max(...ids.map(id=>Math.max(...solutions.map(s=>s.values[id]))-Math.min(...solutions.map(s=>s.values[id]))));
 if(spread>p.iteration.agreement_tolerance)fail('补算多初值不一致');
 const detail=evaluate(solutions[1].values),values=detail.mapped,round=e=>Math.round(e*1e6)/1e6||0;
 const result={schema:'liuren-selected-strength-v1',model:PALACE_MODEL,base_model:baseline.model,profile_sha256:baseline.profile_sha256,
  selected_policy:SELECTED_POLICY,chart_sha256:hash(c),scope:q.mode,season_profile:q.season_profile,season_basis:q.season_basis,
  actors:ids.map(id=>{const b=by.get(id);return {...actors.get(id),single_palace:round(b.strength),single_palace_level:strengthBand(b.strength),
   adjusted:round(values[id]),delta:round(values[id]-b.strength),level:strengthBand(values[id])};}),
  applied_relations:detail.ledger.map(e=>({...e,received:round(e.received),source_cost:round(e.source_cost)})),already_local_or_blocked:skipped,
  interpretation:'分数描述力量；弱仍可作用，0不等于整件事绝对不成。取用与关系适用性由AI依原法判断；未选关系及合局数值未补入。',
  receipt_sha256:hash({chart:hash(c),profile:baseline.profile_sha256,selected:SELECTED_POLICY,request:q,...(evaluation?{evaluation}:{})}),
   convergence:{residual:solutions[1].residual,spread},
   coverage:{actors:ids,submitted_relations:links.length,computed_relations:edges.length,
    skipped_relations:skipped.length,unselected_palaces_updated:false,
    semantic_role_validated:false,relation_applicability_validated:false,event_verdict_supported:false,
    qualitative_conditions:'刑冲合害、神煞专项、制救通达与兑现仍依原法；合局数值暂缓'}};
 if(q.review){
  // Inspection is deliberately limited to declared actors. Facts are not
  // automatically promoted to effective links or added to the calculation.
  const candidates=[];
  for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++){
   const a=by.get(ids[i]),b=by.get(ids[j]),pair=[a.id,b.id].sort().join('|');
   const facts=relations(a.symbol,b.symbol),reverse=relations(b.symbol,a.symbol);
   const conditions=[...facts,...reverse.filter(x=>x.type==='刑')].filter((x,k,all)=>
    all.findIndex(v=>v.type===x.type&&v.from===x.from&&v.to===x.to)===k);
   const direct=baseline.audit.ledger.filter(e=>
    [e.source,e.target].sort().join('|')===pair&&(!e.owner||e.owner===a.id||e.owner===b.id));
   candidates.push({actors:[a.id,b.id],facts:conditions,
    submitted:seen.has(pair),already_local:direct.length>0,
    numeric_use:'仅事实核查；是否切题、可作用及是否提交补算由原法裁定'});
  }
  const other=q.season_profile==='four-seasons'?'quarter-earth':'four-seasons';
  const comparison=calculateSelectedStrength(c,{...q,review:false,season_profile:other,
   season_basis:'双表敏感性核查；不据分数选择采用表'}, {evaluation,voidMode,quantityView:false});
  result.review={schema:'liuren-strength-review-v1',
   state_basis:ids.map(id=>{const b=by.get(id);return {id,kind:b.kind,ground:b.ground,carrier:b.carrier??null,month:baseline.context.month,month_qi:b.season,
    references:b.refs,original_void:baseline.original_void,evaluation_void:baseline.evaluation_void,
    void_self:b.kind==='branch'?baseline.evaluation_void.includes(b.symbol):null,
    void_ground:baseline.evaluation_void.includes(b.ground),
    void_carrier:b.carrier?baseline.evaluation_void.includes(b.carrier):null,
    void_upper:b.upper?baseline.evaluation_void.includes(b.upper):null,
    void_retention:b.retention,tomb_access:b.access,base:b.base,local_net:b.delta,
    outward_restriction:b.goal_loss??0,
    direct_relations:baseline.audit.ledger.filter(e=>e.target===id||e.source===id),
    pending_action_conditions:b.pending??[]};}),
   relation_candidates:candidates,
   season_comparison:{selected_profile:q.season_profile,comparison_profile:other,
    rows:result.actors.map(a=>{const b=comparison.actors.find(v=>v.id===a.id);return {id:a.id,
     selected:a.adjusted,comparison:b.adjusted,delta:round(b.adjusted-a.adjusted)};}),
    interpretation:'同一对象与关系快照分别核算；差异不决定采用表，不平均、不计两票'},
   limitation:'仅核已声明对象；未声明对象与专项条件未穷尽。pending是计算适配提示，不是成败裁决或新待办清单'};
 }
 if(quantityView){
  // Rebuild the same graph and selected links without numeric void retention.
  // Never divide a rounded, already-attenuated score to invent a counterfactual.
  const without=calculateSelectedStrength(c,{...q,review:false},{evaluation,voidMode:'excluded',quantityView:false});
  result.quantity_basis={schema:'liuren-quantity-strength-basis-v1',void_excluded_by_recomputation:true,
   scope:q.mode,baseline_reference:STRENGTH_PROFILE.baseline,calibration:'research-unvalidated',
   rows:ids.map(id=>{const b=by.get(id);return {id,seasonal:b.season,
    with_void:result.actors.find(a=>a.id===id).adjusted,
    without_void:without.actors.find(a=>a.id===id).adjusted,
    void_self:b.kind==='branch'?baseline.evaluation_void.includes(b.symbol):false,
    void_ground:baseline.evaluation_void.includes(b.ground),
    void_carrier:b.carrier?baseline.evaluation_void.includes(b.carrier):false,
    body_base:b.base,tomb_access:b.access,local_net:b.delta,
    outward_restriction:b.goal_loss??0};}),
   limitations:'不含空亡视图将本次图中各源与目标的数值空减一起移除，重算原关系；保留事实空位、墓与生克。5是模型基准，非已校准的数量中气；不裁成败，不映射量级。'};
 }
 return result;
}

import fs from 'node:fs/promises';
import {buildFacts,element,fiveRelation,seasonal,relations,xunFacts,ZHI,GAN,hash} from './liuren-deterministic.mjs';
import {clip,mean,uid,pairKey,hasRelation,combineLosses,voidRetention,referenceBase,openingRatio,
 groupCandidates,groupStrength,activation,directedEffect,goldFireAllocation,specialCandidates,fiveRole,localFormations,globalQi,cappedLossItems} from './liuren-strength-rules.mjs';

export const STRENGTH_PROFILE=JSON.parse(await fs.readFile(new URL('./liuren-strength-profile.json',import.meta.url),'utf8'));
const phaseNames=['opening','development','outcome'];
const round=x=>Math.round(x*10)/10;
const error=message=>{throw Error('LIUREN_STRENGTH: '+message);};
function normalizeContext(c,ctx){
 const o=structuredClone(ctx),month=o.evaluation?.month_branch??c.month_branch;
 if(!ZHI.includes(month))error('评价月支无效');
 if(o.evaluation&&!o.evaluation.basis)error('时间条件更新必须给出依据，不重新排原盘');
 const season=o.seasonProfile??(!'辰未戌丑'.includes(month)?'four-seasons':null);
 if(!['four-seasons','quarter-earth'].includes(season))error('季月须显式选择seasonProfile及采用依据');
 if(!o.seasonBasis)error('须给出seasonBasis，不能按结果自动择表');
 const phase=o.phase??'outcome';if(!phaseNames.includes(phase))error('phase须为opening/development/outcome');
 const voidMode=o.voidMode??'included';if(!['included','excluded'].includes(voidMode))error('voidMode须为included/excluded');
 if(o.selectedSubjects?.some(s=>!ZHI.includes(s)))error('selectedSubjects只接受支，其他九干不默认接入');
 if(o.evaluation?.day_pillar)xunFacts(o.evaluation.day_pillar);
 const goal=o.goal??{id:'day',target:'S:'+c.day_stem,mode:'external'};
 if(!['external','cooperate','movement'].includes(goal.mode))error('goal.mode无效');
 return {...o,month,seasonProfile:season,phase,voidMode,goal,effectRules:o.effectRules??[],shenshaRules:o.shenshaRules??[],groupModes:o.groupModes??{},includeGroupEffects:false};
}
function graphFrom(c,d,o,p){
 const old=p.inherited,nodes=[];
 const voidBranches=o.evaluation?.day_pillar?xunFacts(o.evaluation.day_pillar).void_branches:d.xun.void_branches;
 function addNode(v,refs){
  const season=seasonal(v.symbol,o.month,o.seasonProfile),basis=referenceBase(season,refs,p);
  const retention=v.kind==='branch'&&o.voidMode!=='excluded'?voidRetention(season,voidBranches.includes(v.symbol),voidBranches.includes(v.ground),p):1;
  nodes.push({...v,season,...basis,retention,seed:retention*clip(basis.base*basis.access)});
 }
 for(const n of d.nodes){
  addNode({id:'T:'+n.symbol,symbol:n.symbol,kind:'branch',ground:n.ground,general:n.general,direct_yin:n.direct_yin,
   lessons:n.lesson_slots,transmissions:n.transmission_slots,void_self:d.xun.void_branches.includes(n.symbol),void_ground:d.xun.void_branches.includes(n.ground)},
   [{place:n.ground,state:n.growth.ground,weight:old.growth_weights.branch.ground},{place:n.direct_yin,state:n.growth.yin,weight:old.growth_weights.branch.direct_yin}]);
  addNode({id:'J:'+n.general,symbol:n.general,kind:'general',carrier:n.symbol,ground:n.ground,lessons:n.lesson_slots,transmissions:n.transmission_slots},
   [{place:n.symbol,state:n.general_growth.branch,weight:old.growth_weights.general.carrier},{place:n.ground,state:n.general_growth.ground,weight:old.growth_weights.general.ground}]);
  const season=seasonal(n.ground,o.month,o.seasonProfile),base=p.baseline*old.season[season];
  nodes.push({id:'D:'+n.ground,symbol:n.ground,kind:'ground',season,base,access:1,retention:1,seed:base,refs:[]});
 }
 addNode({id:'S:'+d.day.symbol,symbol:d.day.symbol,kind:'day',ground:d.day.home,upper:d.day.upper,direct_yin:d.day.direct_yin,lessons:[],transmissions:[]},
  [{place:d.day.upper,state:d.day.growth.upper,weight:1}]);
 const by=new Map(nodes.map(n=>[n.id,n]));

}
function evaluate(graph,values,p,{depth,lower,before}){
 const gates=edgesAt(graph,depth,values,p),delta=Object.fromEntries(graph.nodes.map(n=>[n.id,0])),ledger=[];
 const subject=graph.by.get(graph.goal.target),old=p.inherited;
 for(const e of gates.edges){
  const a=graph.by.get(e.source),b=graph.by.get(e.target);
  const sourceValue=e.route==='yin'&&e.owner!==e.source?lower[e.source]:values[e.source];
  const targetValue=e.route==='yin'&&e.owner!==e.target?lower[e.target]:values[e.target];
  let tau=1;
  if(e.target===subject.id&&a.kind==='branch'&&['生','克'].includes(e.type))tau=1-greedyLoss(a,graph,e.route==='yin'?lower:values,p);
  const flow=directedEffect(e.type,sourceValue,targetValue,e.gate,a.seed,p,tau);
  let positiveReplacement=0,special=null;
  // Only the explicit stem 庚/辛 fire/long-life example is adapted; not all metal branches.
  if(e.type==='克'&&a.symbol==='巳'&&b.kind==='day'&&['庚','辛'].includes(b.symbol)&&b.refs.some(r=>r.place==='巳'&&r.state==='长生')){
   const positive=b.refs.filter(r=>r.place==='巳').reduce((sum,r)=>sum+p.baseline*old.season[b.season]*r.weight*Math.max(0,r.body_ratio-1),0);
   const j=graph.nodes.find(n=>n.kind==='general'&&n.carrier==='巳');
   const jr=j?fiveRelation(j.symbol,b.symbol):null;
   const support=jr==='生'?old.relations.support*values[j.id]:0,control=jr==='克'?old.relations.control*values[j.id]:0;
   special=goldFireAllocation(positive,-flow.received,sourceValue,values[b.id],support,control);
   positiveReplacement=special.positive-positive;flow.received=-special.negative;flow.cost=old.relations.control_cost_ratio*special.negative;
  }
  const targetBooked=b.kind!=='ground'&&(!e.owner||e.owner===b.id),sourceBooked=a.kind!=='ground'&&(!e.owner||e.owner===a.id);
  if(targetBooked)delta[b.id]+=flow.received+positiveReplacement;
  if(sourceBooked)delta[a.id]-=flow.cost;
  ledger.push({...e,source_strength:sourceValue,target_strength:targetValue,tau,received:targetBooked?flow.received:0,
   source_cost:sourceBooked?flow.cost:0,reference_reallocation:targetBooked?positiveReplacement:0,special,
   local_observation:e.owner??null,observed_received:flow.received,observed_source_cost:flow.cost});
 }
 const mapped={},access={};
 for(const n of graph.nodes){
  access[n.id]=accessFor(n,graph,values,before??values,p);
  mapped[n.id]=n.kind==='ground'?n.seed:n.retention*clip(access[n.id]*(n.base+delta[n.id]));
 }
 return {mapped,delta,ledger,access,groups:gates.groups};

  const greedyItems=cappedLossItems([...greedy,...move],old.constraints.cap_greedy);
  const greedAndMovement=combineLosses(greedyItems);
  const goalLoss=combineLosses([...bindItems,...greedyItems]);
  const act=activation(n,o.phase,p),potential=clip(E[n.id]*act*(1-disruption)*(1-goalLoss));
  for(const v of virtues)virtueRoutes.push({...v,source:n.id,capacity:potential});
  const problems=pending.filter(x=>x.id===n.id).map(x=>x.rule);
  const harmfulCoefficient=old.harm_tendency[n.season];
  const incomingHarm=solution.ledger.filter(x=>x.target===n.id&&x.type==='克').reduce((sum,x)=>sum-x.received*old.harm_tendency[graph.by.get(x.source).season],0);
  rows.push({id:n.id,strength:E[n.id],action_index:problems.length?null:potential,partial_action_index:potential,
   activation:act,disruption,binding,greedy:greedAndMovement,goal_loss:goalLoss,virtue_reduction:0,
   interpretation:{harm_tendency:harmfulCoefficient,favorable_tendency:old.favorable_tendency[n.season],
    qualified_adverse_index:o.adverseTargets?.includes(n.id)?incomingHarm:null},
   pending:problems,mechanisms:{disruption:disrupt,binding:bind,movement:move,releases:releaseBindings}});
 }
 for(const v of virtueRoutes){
  const target=rows.find(x=>x.id===v.target),source=rows.find(x=>x.id===v.source);
  const edges=solution.ledger.filter(x=>x.source===v.source&&x.target===v.target&&(!x.owner||x.owner===v.target));
  const gate=v.source===v.target?1:Math.max(0,...edges.map(x=>x.gate));
  if(!gate||source.pending.length){
   addPending(target.id,v.item,!gate?'德解未见有效定向通路':'德源自身作用尚有未适配条件');
   target.pending.push(v.item);target.action_index=null;continue;
  }
  target.virtue_reduction=Math.max(target.virtue_reduction,old.virtue_max_reduction*v.capacity*gate/10);
  mechanisms.push({id:target.id,rule:'定向德解',source:v.source,gate,cause:v.item});
 }
 for(const row of rows)if(row.interpretation.qualified_adverse_index!==null)row.interpretation.qualified_adverse_index*=1-row.virtue_reduction;
 return {rows,pending:[...new Map(pending.map(x=>[uid(x.id,x.rule),x])).values()],mechanisms};
}

export function computeStrength(c,context={}, {profile=STRENGTH_PROFILE,shensha}={}){
 const p=structuredClone(profile),o=normalizeContext(c,context),d=buildFacts(c),graph=graphFrom(c,d,o,p),solution=solveGraph(graph,p);
 for(const rule of o.shenshaRules)if(!(shensha?.items??[]).some(x=>x.status==='resolved'&&x.id===rule.id))error('神煞裁用不在本盘采用表 '+rule.id);
 const action=actions(graph,solution,c,o,p,shensha);
