 const unique=[...causes].map(([cause,loss])=>({cause,loss})),raw=combineLosses(unique);
 if(raw<=cap)return unique;
 if(cap===0)return [];
 const exponent=Math.log(1-cap)/Math.log(Math.max(1e-15,1-raw));
 return unique.map(x=>({...x,loss:1-(1-x.loss)**exponent}));
}
